import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    op = [h[1] for h in history]
    me = [h[0] for h in history]

    opp_c = sum(1 for x in op if x == 'C')
    opp_d = n - opp_c
    my_c = sum(1 for x in me if x == 'C')
    my_d = n - my_c
    rate = opp_c / n

    rounds_left = 100 - n

    # Find current opponent runs
    run_d = 0
    for x in reversed(op):
        if x == 'D':
            run_d += 1
        else:
            break
    run_c = 0
    for x in reversed(op):
        if x == 'C':
            run_c += 1
        else:
            break

    # My current run
    my_run_d = 0
    for x in reversed(me):
        if x == 'D':
            my_run_d += 1
        else:
            break
    my_run_c = 0
    for x in reversed(me):
        if x == 'C':
            my_run_c += 1
        else:
            break

    # Endgame: last 3 rounds defect hard unless opponent is essentially pure cooperator
    if rounds_left <= 3:
        if rate >= 0.95 and opp_d <= 2:
            return 'C'
        return 'D'

    # Last 10 rounds: lean aggressive if opponent has meaningful defection
    if rounds_left <= 10:
        if rate >= 0.9 and opp_d <= 2:
            return 'C'
        if rate >= 0.8 and opp_d <= 4 and my_c >= my_d:
            return 'C'
        return 'D'

    # Very last stretch of generous play only if opponent extremely clean
    if rounds_left <= 20:
        if rate >= 0.92 and run_d == 0:
            return 'C'
        if opp_d == 0:
            return 'C'

    # Pure always-defect detection
    if n >= 8 and opp_c == 0:
        # opponent never cooperated; defect, but rare probe
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Nearly always-defect
    if n >= 10 and rate < 0.08:
        if rng.random() < 0.03:
            return 'C'
        return 'D'

    # Pure / nearly pure cooperator
    if n >= 10 and rate > 0.93:
        # Exploit but sprinkle cooperation to preserve stream & avoid pathology
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Strong cooperator exploitation zone in mid-game
    if n >= 15 and rate > 0.85 and opp_d >= 1:
        # if they've been very forgiving of our defections, push harder
        if my_d >= 3 and run_c >= 3:
            if rng.random() < 0.85:
                return 'D'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    # If opponent is currently in a long defection streak, punish
    if run_d >= 2:
        # If they've been mostly good, forgive after one strike to avoid DD trap
        if rate > 0.75 and run_d == 2 and run_c >= 0:
            return 'C'
        if run_d >= 4:
            # long streak: maybe test C to see if they reciprocate
            if my_run_d >= 3 and rng.random() < 0.18:
                return 'C'
            return 'D'
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent defected once recently
    if op[-1] == 'D':
        # TFT-style retaliation, mild forgiveness
        if rate > 0.85:
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        if rate > 0.6:
            if rng.random() < 0.25:
                return 'C'
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent cooperated last round

    # If we've been defecting too long, re-cooperate to reset
    if my_run_d >= 3:
        return 'C'

    # Punish a short defection streak in our own record by returning to cooperation
    if my_run_d == 1 and op[-1] == 'C':
        # we defected, they forgave one: be careful, either re-cooperate or exploit if they keep cooperating
        recent5_op = op[-5:]
        recent5_c = sum(1 for x in recent5_op if x == 'C')
        if recent5_c >= 4 and rate > 0.75:
            # opportunistic: they forgive often, lean D
            if rng.random() < 0.5:
                return 'D'
        return 'C'

    # Opponent has been very cooperative; occasional probing but mostly C
    if rate > 0.85:
        if n > 12 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # Moderate opponent
    if rate > 0.6:
        if rng.random() < 0.04:
            return 'D'
        return 'C'

    # Low cooperation: defect more often but still probe cooperation
    if rate > 0.35:
        if rng.random() < 0.35:
            return 'C'
        return 'D'

    # Very low: mostly defect with occasional forgiveness
    if rng.random() < 0.1:
        return 'C'
    return 'D'
